import{_ as t,o as a,c as s,ah as r}from"./chunks/framework.Xx6Iwo0O.js";const p=JSON.parse('{"title":"Phase 3: v1, ready for its first real install","description":"","frontmatter":{"title":"Phase 3: v1, ready for its first real install","date":"2026-11-01T00:00:00.000Z","phase":3,"status":"gate"},"headers":[],"relativePath":"blog/v1-release.md","filePath":"blog/v1-release.md"}'),i={name:"blog/v1-release.md"};function n(o,e,l,h,d,c){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="phase-3-v1-ready-for-its-first-real-install" tabindex="-1">Phase 3: v1, ready for its first real install <a class="header-anchor" href="#phase-3-v1-ready-for-its-first-real-install" aria-label="Permalink to &quot;Phase 3: v1, ready for its first real install&quot;">​</a></h1><p>Phase 2 made a game you could design, publish and play. Phase 3 set out to prove it: every user scenario run end to end on both backends, performance and accessibility measured, more browsers tested, a deployment that installs without the internet, and a final review. All of that is done. One step is left before the release: installing it on the real hardware, which is with the product owner. Until then, v1 is a release candidate.</p><p>There were no work-in-progress posts during Phase 3, so this post is the whole story of the phase.</p><h2 id="what-changed-in-phase-3" tabindex="-1">What changed in Phase 3 <a class="header-anchor" href="#what-changed-in-phase-3" aria-label="Permalink to &quot;What changed in Phase 3&quot;">​</a></h2><ul><li><strong>The user scenarios, on both backends.</strong> Nine scenarios, from designing and publishing a game to two people sharing one role, now run as browser tests on the in-browser mock and, wherever a server is involved, on a real ejabberd server. What they found is fixed, and each fix has a test.</li><li><strong>Performance at scale.</strong> A generated game of 50 roles, 30 rooms and a 10,000-message room is measured on every run. Opening the big room takes well under a second, typing never lags, and a message reaches four open panes in about a twentieth of a second.</li><li><strong>Accessibility.</strong> Every screen is checked against WCAG 2.2 AA with an automated checker, and the main tasks are tested with the keyboard alone. The gaps it found, such as unread counts that screen readers could not hear, are fixed.</li><li><strong>Browsers.</strong> The tests now also run on Firefox and on Safari&#39;s engine. Chrome and Edge are fully supported; Firefox and Safari are best effort, and the two problems still open are listed in the release notes.</li><li><strong>A narrow-window layout.</strong> When space is short, the out-of-game column becomes a tab of its own instead of squeezing the rooms.</li><li><strong>Ids that never change.</strong> Forces, roles and rooms are now identified by GUIDs, and each role has a separate login name. Renaming anything is safe, and a deleted role&#39;s old messages still show its name, marked as deleted. A role&#39;s login name is fixed once it is published: the server cannot rename an account, so publishing is refused, with the reason, rather than quietly making a new account.</li><li><strong>Objectives by the umpire only.</strong> Only the admin, as umpire, writes a force&#39;s objectives. Every White Force role reads all of them.</li><li><strong>The reference deployment.</strong> One container serves the client and the server on one secure address. It installs from a single bundle on a machine with no internet access, works with the organisation&#39;s certificate authority or a small one made for the exercise, and backs up and restores while it runs. The <a href="./../deployment.html">deployment page</a> has the outline.</li></ul><h2 id="how-it-was-checked" tabindex="-1">How it was checked <a class="header-anchor" href="#how-it-was-checked" aria-label="Permalink to &quot;How it was checked&quot;">​</a></h2><p>Every change runs the unit tests, the browser tests on the mock, and the contract, admin, publishing, audit and deployment suites against a real ejabberd server. The install itself is tested inside a container with its network switched off, and then the whole contract suite runs against that installation.</p><p>Before this gate, a reviewer read the security-relevant code again, independently of the people who wrote it. It found that a player&#39;s own role could only be found by listing the server&#39;s documents, so a server that refused the listing left the player with no rooms; that is fixed, and the client now finds its role directly. It also found ways an imported design could rename or reuse a published login name; publishing and the audit now refuse both. Nothing it found was rated high or critical, and each finding is either fixed with a test or recorded with its reason.</p><h2 id="what-is-still-open" tabindex="-1">What is still open <a class="header-anchor" href="#what-is-still-open" aria-label="Permalink to &quot;What is still open&quot;">​</a></h2><ul><li><strong>The real-hardware install.</strong> The deployment has only been installed in containers. The first install on the real host is with the product owner, with a checklist in the operator&#39;s guide. This post will say when it is done.</li><li><strong>Certificates.</strong> Whether the customer&#39;s own certificate authority issues the server&#39;s certificate, or a small one made for the exercise does, is still to be decided. The scripts support both.</li><li><strong>Moving an earlier game.</strong> A server published by an earlier build is not upgraded in place: export the design, import it, reset the server and publish. No game has run for real yet, so nothing is lost today.</li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><p>After the real-hardware check, v1 is released, with the release notes in the repository (<code>RELEASE-NOTES.md</code>) as its description. The next features are already specified: structured form rooms with message templates, and maps with force assets.</p>',12)])])}const f=t(i,[["render",n]]);export{p as __pageData,f as default};
